
CREATE TABLE inmobix.realstates (
    id bigint NOT NULL,
    address character varying(255),
    bathrooms integer NOT NULL,
    bedrooms integer NOT NULL,
    description character varying(255),
    has_parking boolean NOT NULL,
    picture character varying(255),
    price bigint NOT NULL,
    title character varying(255)
);

ALTER TABLE inmobix.realstates ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME inmobix.realstates_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


SELECT pg_catalog.setval('inmobix.realstates_id_seq', 26, true);

ALTER TABLE ONLY inmobix.realstates
    ADD CONSTRAINT realstates_pkey PRIMARY KEY (id);
